CREATE TABLE IF NOT EXISTS entities (id text PRIMARY KEY, slug text UNIQUE NOT NULL, kind text NOT NULL CHECK(kind IN ('Concept','Tool','Company','Project','Technology')), name text NOT NULL, aliases jsonb NOT NULL DEFAULT '[]', summary text NOT NULL, details jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS sources (id text PRIMARY KEY, url text UNIQUE NOT NULL, title text NOT NULL, tier text NOT NULL CHECK(tier IN ('S','A','B','C')), adapter text NOT NULL, entity_id text REFERENCES entities(id), status text NOT NULL DEFAULT 'UNAVAILABLE' CHECK(status IN ('AVAILABLE','PARTIAL','STALE','UNAVAILABLE','RATE_LIMITED','ERROR')), retrieved_at timestamptz, published_at timestamptz, error text, metadata jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS source_observations (id text PRIMARY KEY, source_id text NOT NULL REFERENCES sources(id), retrieved_at timestamptz NOT NULL, status text NOT NULL, content_hash text, metadata jsonb NOT NULL, error text);
CREATE TABLE IF NOT EXISTS facts (id text PRIMARY KEY, entity_id text NOT NULL REFERENCES entities(id), predicate text NOT NULL, value jsonb NOT NULL, source_id text NOT NULL REFERENCES sources(id), kind text NOT NULL CHECK(kind IN ('FACT','ANALYSIS')), confidence double precision NOT NULL CHECK(confidence BETWEEN 0 AND 1), discovered_at timestamptz NOT NULL, published_at timestamptz, valid_from timestamptz NOT NULL, valid_until timestamptz, last_verified_at timestamptz NOT NULL, CHECK(valid_until IS NULL OR valid_until>=valid_from));
CREATE UNIQUE INDEX IF NOT EXISTS facts_current ON facts(entity_id,predicate,source_id) WHERE valid_until IS NULL;
CREATE INDEX IF NOT EXISTS facts_time ON facts(entity_id, valid_from, valid_until);
CREATE TABLE IF NOT EXISTS fact_verifications (fact_id text REFERENCES facts(id), source_id text REFERENCES sources(id), verified_at timestamptz NOT NULL, PRIMARY KEY(fact_id,verified_at));
CREATE TABLE IF NOT EXISTS relationships (id text PRIMARY KEY, from_id text NOT NULL REFERENCES entities(id), to_id text NOT NULL REFERENCES entities(id), predicate text NOT NULL, source_id text REFERENCES sources(id), kind text NOT NULL DEFAULT 'ANALYSIS', valid_from timestamptz NOT NULL, valid_until timestamptz, discovered_at timestamptz NOT NULL, confidence double precision NOT NULL CHECK(confidence BETWEEN 0 AND 1));
CREATE TABLE IF NOT EXISTS events (id text PRIMARY KEY, entity_id text NOT NULL REFERENCES entities(id), source_id text NOT NULL REFERENCES sources(id), title text NOT NULL, event_type text NOT NULL, published_at timestamptz NOT NULL, discovered_at timestamptz NOT NULL, url text NOT NULL);
CREATE TABLE IF NOT EXISTS signals (id text PRIMARY KEY, entity_id text NOT NULL REFERENCES entities(id), source_id text NOT NULL REFERENCES sources(id), metric text NOT NULL, value double precision, unit text NOT NULL, status text NOT NULL, observed_at timestamptz NOT NULL);
CREATE INDEX IF NOT EXISTS signals_history ON signals(entity_id,metric,observed_at);
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY, email text UNIQUE NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS sessions (token_hash text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS user_contexts (user_id text PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, context jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS research_runs (id text PRIMARY KEY, user_id text REFERENCES users(id) ON DELETE CASCADE, query text NOT NULL, intent text NOT NULL, status text NOT NULL, stages jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS card_cache (cache_key text PRIMARY KEY, result jsonb NOT NULL, expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS llm_usage (id text PRIMARY KEY, user_id text REFERENCES users(id) ON DELETE CASCADE, run_id text REFERENCES research_runs(id) ON DELETE SET NULL, provider text NOT NULL, model text NOT NULL, task_type text NOT NULL, input_tokens integer, output_tokens integer, estimated_cost numeric, currency text NOT NULL DEFAULT 'USD', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_log (id text PRIMARY KEY, user_id text REFERENCES users(id) ON DELETE SET NULL, action text NOT NULL, metadata jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS rate_limits (bucket text PRIMARY KEY, count integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE TABLE IF NOT EXISTS job_locks (name text PRIMARY KEY, expires_at timestamptz NOT NULL);
